using DynamicBoneDistributionEditor;
using UnityEngine;
using System.Text.Json;
int passed=0,failed=0;var checks=new List<object>();
void Check(string name,Action test){try{test();passed++;checks.Add(new{name,passed=true});}catch(Exception e){failed++;checks.Add(new{name,passed=false,error=e.GetType().Name+": "+e.Message});}}
void Require(bool ok,string reason){if(!ok)throw new Exception(reason);}
DynamicBone Bone(string root="same")=>new(){m_Root=new Transform{name=root}};
(DBDECharaController c,GameObject cloth,DBDEDynamicBoneEdit edit,DynamicBone target) Setup(){DBDE.UI=new();var target=Bone();var edit=new DBDEDynamicBoneEdit{PrimaryDynamicBone=Bone()};var c=new DBDECharaController();c.DistributionEdits[0]=new(){edit};return(c,new(){Bones=new[]{target}},edit,target);}
Check("valid same-name binding and active stack preserved",()=>{var x=Setup();x.c.ClothesChanged(x.cloth);Require(x.edit.ReferCalls==1&&x.edit.ApplyCalls==1&&x.edit.UpdateCalls==1&&x.edit.LastBound==x.target,"valid path changed");});
Check("different root remains unmatched",()=>{var x=Setup();x.target.m_Root.name="other";x.c.ClothesChanged(x.cloth);Require(x.edit.ReferCalls==0&&x.edit.UpdateCalls==1,"root matching broadened");});
Check("first matching candidate preserved",()=>{var x=Setup();var second=Bone();x.cloth.Bones=new[]{x.target,second};x.c.ClothesChanged(x.cloth);Require(x.edit.LastBound==x.target,"first match changed");});
foreach(var kind in new[]{"null-bone","destroyed-bone","null-root","destroyed-root"})Check("candidate "+kind+" skipped while later valid binds",()=>{var x=Setup();DynamicBone bad=kind=="null-bone"?null:Bone();if(kind=="destroyed-bone")bad.Destroyed=true;if(kind=="null-root")bad.m_Root=null;if(kind=="destroyed-root")bad.m_Root.Destroyed=true;x.cloth.Bones=new[]{bad,x.target};x.c.ClothesChanged(x.cloth);Require(x.edit.LastBound==x.target,"invalid candidate blocked valid later one");});
foreach(var kind in new[]{"null-primary","destroyed-primary","null-primary-root","destroyed-primary-root"})Check(kind+" no spurious bind and valid next edit continues",()=>{var x=Setup();var old=x.edit;if(kind=="null-primary")old.PrimaryDynamicBone=null;if(kind=="destroyed-primary")old.PrimaryDynamicBone.Destroyed=true;if(kind=="null-primary-root")old.PrimaryDynamicBone.m_Root=null;if(kind=="destroyed-primary-root")old.PrimaryDynamicBone.m_Root.Destroyed=true;var good=new DBDEDynamicBoneEdit{PrimaryDynamicBone=Bone()};x.c.DistributionEdits[0].Add(good);x.c.ClothesChanged(x.cloth);Require(old.ReferCalls==0&&good.LastBound==x.target,"lost valid continuation or rebound invalid edit");});
Check("null edit skipped without deleting saved entries",()=>{var x=Setup();x.c.DistributionEdits[0].Insert(0,null);x.c.ClothesChanged(x.cloth);Require(x.c.DistributionEdits[0].Count==2&&x.edit.ApplyCalls==1,"edit data removed or valid edit lost");});
Check("loading early return has no mutation",()=>{var x=Setup();x.c.IsLoading=true;DBDE.UI.UpdateUIWhileOpen=false;x.c.ClothesChanged(x.cloth);Require(x.c.RefreshCalls==0&&!DBDE.UI.UpdateUIWhileOpen,"loading path mutated");});
Check("null clothing ignored before UI write",()=>{var x=Setup();x.c.ClothesChanged(null);Require(x.c.RefreshCalls==0&&DBDE.UI.UpdateUIWhileOpen,"null clothing touched UI");});
Check("destroyed clothing ignored before UI write",()=>{var x=Setup();x.cloth.Destroyed=true;x.c.ClothesChanged(x.cloth);Require(x.c.RefreshCalls==0&&DBDE.UI.UpdateUIWhileOpen,"destroyed clothing touched UI");});
Check("initial disabled UI preserved",()=>{var x=Setup();DBDE.UI.UpdateUIWhileOpen=false;x.c.ClothesChanged(x.cloth);Require(!DBDE.UI.UpdateUIWhileOpen,"overrode outer UI state");});
Check("absent UI does not prevent data operation",()=>{var x=Setup();DBDE.UI=null;x.c.ClothesChanged(x.cloth);Require(x.edit.ApplyCalls==1,"UI absence blocked data");});
Check("refresh exception propagates and UI restored",()=>{var x=Setup();x.c.FailRefresh=true;bool thrown=false;try{x.c.ClothesChanged(x.cloth);}catch(InvalidOperationException){thrown=true;}Require(thrown&&DBDE.UI.UpdateUIWhileOpen,"swallowed exception or stuck UI");});
Check("apply exception propagates and UI restored",()=>{var x=Setup();x.edit.FailApply=true;bool thrown=false;try{x.c.ClothesChanged(x.cloth);}catch(InvalidOperationException){thrown=true;}Require(thrown&&DBDE.UI.UpdateUIWhileOpen,"swallowed exception or stuck UI");});
Check("replacement UI left untouched",()=>{var x=Setup();var original=DBDE.UI;var next=new DBDEUI{UpdateUIWhileOpen=false};x.c.ReplaceUiDuringRefresh=next;x.c.ClothesChanged(x.cloth);Require(original.UpdateUIWhileOpen&&!next.UpdateUIWhileOpen,"restored wrong UI instance");});
Check("unrelated coordinates unchanged",()=>{var x=Setup();var other=new DBDEDynamicBoneEdit{PrimaryDynamicBone=Bone()};x.c.DistributionEdits[1]=new(){other};x.c.ClothesChanged(x.cloth);Require(other.ReferCalls==0&&x.c.DistributionEdits[1].Count==1,"cross-coordinate mutation");});
Check("no matching coordinate still restores UI",()=>{var x=Setup();x.c.DistributionEdits.Clear();x.c.ClothesChanged(x.cloth);Require(x.c.RefreshCalls==1&&DBDE.UI.UpdateUIWhileOpen,"no-coordinate failure");});
Console.WriteLine(JsonSerializer.Serialize(new{passed,failed,checks},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
